#include "resident/checkpoint/checkpoint_economic_index_copy.hpp"
// 财政有限观察只枚举已经合法的原评税来源；不泄露未授权记录数量、余额或未来政策。
#include "fiscal_settlement_view.hpp"
#include "resident/domains/organization/organization_model.hpp"
namespace hanmo::resident {
namespace {
// 源索引和游标必须绑定完整世界身份，不能跨冷恢复或换人续读。
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
// 公职身份键保留任期与本人，不能只凭组织名复用旧源。
LocalEconomyAuthorityKey authority_key(const ActingAuthority& a){return {a.organization_id,a.office_id,a.authority_epoch,a.actor_id};}
// 机构税务需要该地点与对应公账的明确读grant；组织纳税者只能读取自己原付款账户的责任。
bool may_read(const OrganizationRead& organizations,const FiscalSourceAssessment& assessment,const FiscalPolicySnapshot& policy,const ActingAuthority& authority){
    if(!organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::site,policy.site_id},0).ok)return false;
    StableId account;if(authority.organization_id==policy.organization_id)account=policy.public_wallet_id;else if(assessment.owner.kind==Owner::Kind::organization&&assessment.owner.id==authority.organization_id)account=assessment.wallet_id;else return false;
    return organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::account,account},0).ok;
}
// 字段编码复用原经济页的完整身份和cursor协议，财政只追加自己的只读行。
BoundaryValue common_page_fields(const FiscalSettlementPage& page){LocalEconomyPage common;common.identity=page.identity;common.observer_actor_id=page.observer_actor_id;common.place_id=page.place_id;common.cursor=page.cursor;common.scanned=page.scanned;common.next_cursor=page.next_cursor;common.authorities=page.authorities;return encode_local_economy_page(common);}
}
// 只从当前本人真实Office生成候选源，家庭没有人物控制读口时不会凭亲属或头衔增加权限。
FiscalSettlementIndex build_fiscal_settlement_index(const CommonStore& common,const FiscalSettlementState& state,const OrganizationState& organization,const OrganizationRead& organizations){
    FiscalSettlementIndex index;index.identity=common.state().identity;index.observer_actor_id=index_memory::copy(index.text_memory,common.state().metadata.player_actor_id);const auto* actor=common.actor(index.observer_actor_id);auto location=common.resolved_location(index.observer_actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!actor||!actor->alive||!here)return index;index.place_id=index_memory::copy(index.text_memory,here->place_id);
    for(const auto& row:organization.offices.rows()){const auto& office=row.second;if((!office.holder_actor_id||*office.holder_actor_id!=actor->id)&&(!office.deputy_actor_id||*office.deputy_actor_id!=actor->id))continue;CheckpointMemoryCharge authority_memory;auto authority=index_memory::authority(authority_memory,office.organization_id,office.id,office.epoch,actor->id);if(!organizations.authorize(authority,"inspect_local_economy",{ScopeRef::Kind::site,here->place_id},0).ok)continue;index.authorities.push_back(index_memory::copy(index.text_memory,authority));index_memory::authority_entry(index.text_memory,index.sources,authority);}
    for(const auto& row:state.assessments.rows()){const auto* period=state.periods.find(row.second.period_id);if(!period||!period->policy||period->policy->site_id!=here->place_id||period->due_tick>common.tick())continue;for(const auto& authority:index.authorities)if(may_read(organizations,row.second,*period->policy,authority))index_memory::authority_entry(index.text_memory,index.sources,authority).push_back(index_memory::copy(index.text_memory,row.first));}
    return index;
}
// query只遍历合法ID序列；无权限者返回合法空页，未知/远方记录不改变offset与scanned。
Outcome<FiscalSettlementPage> query_fiscal_settlement(const CommonStore& common,const FiscalSettlementState& state,const FiscalSettlementCatalog& catalog,const OrganizationRead& organizations,const FiscalSettlementIndex& index,const LocalEconomyQuery& query){
    const auto fail=[](const StableId& code)->Outcome<FiscalSettlementPage>{return {false,{},common_failure(code).error};};
    if(catalog.version!=1||catalog.districts.empty()||state.version!=1)return fail("FiscalSettlementUnavailable");if(query.observer_actor_id.empty()||query.observer_actor_id!=common.state().metadata.player_actor_id)return fail("LocalEconomyObserverRequired");const auto* actor=common.actor(query.observer_actor_id);auto location=common.resolved_location(query.observer_actor_id);const auto* here=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!actor||!actor->alive||!here||here->place_id!=query.place_id)return fail("LocalEconomyPlaceNotObservable");if(state.last_step_tick!=common.tick())return fail("FiscalSettlementClockMismatch");if(!same_identity(index.identity,common.state().identity)||index.observer_actor_id!=query.observer_actor_id||index.place_id!=query.place_id)return fail("StaleFiscalSettlementIndex");
    const CheckpointVector<StableId> empty;const auto* sources=&empty;
    if(query.authority){const auto& a=*query.authority;if(a.actor_id!=query.observer_actor_id)return fail("LocalEconomyAuthorityActorMismatch");auto allowed=organizations.authorize(a,"inspect_local_economy",{ScopeRef::Kind::site,query.place_id},0);if(!allowed.ok)return {false,{},allowed.error};auto found=index.sources.find(authority_key(a));if(found==index.sources.end())return fail("StaleFiscalSettlementIndex");sources=&found->second;}
    Integer offset=0;if(query.cursor){const auto& c=*query.cursor;if(!same_identity(c.identity,common.state().identity)||c.observer_actor_id!=query.observer_actor_id||c.place_id!=query.place_id||c.authority.has_value()!=query.authority.has_value()||(c.authority&&authority_key(*c.authority)!=authority_key(*query.authority)))return fail("StaleLocalEconomyCursor");offset=c.offset;}if(sources->size()>static_cast<std::size_t>(INT64_MAX)||offset<0||offset>static_cast<Integer>(sources->size()))return fail("InvalidLocalEconomyCursor");
    FiscalSettlementPage page;page.identity=common.state().identity;page.observer_actor_id=query.observer_actor_id;page.place_id=query.place_id;page.cursor=offset;page.authorities.assign(index.authorities.begin(),index.authorities.end());
    while(offset<static_cast<Integer>(sources->size())&&page.rows.size()<static_cast<std::size_t>(local_economy_page_limit)){
        const auto* assessment=state.assessments.find((*sources)[static_cast<std::size_t>(offset++)]);++page.scanned;const auto* period=assessment?state.periods.find(assessment->period_id):nullptr;if(!assessment||!period||!period->policy||!query.authority||period->policy->site_id!=query.place_id||period->due_tick>common.tick()||!may_read(organizations,*assessment,*period->policy,*query.authority))return fail("StaleFiscalSettlementIndex");const auto& policy=*period->policy;
        page.rows.push_back({assessment->id,period->id,assessment->source_id,policy.site_id,policy.jurisdiction_id,policy.organization_id,assessment->grain_item_id,policy.source_fact_id,period->due_tick,assessment->cash.original_due,assessment->cash.paid_amount,assessment->cash.original_due-assessment->cash.paid_amount,assessment->grain.original_due,assessment->grain.paid_amount,assessment->grain.original_due-assessment->grain.paid_amount,assessment->produced_grain,assessment->civilian_grain_reserve,policy.mode});
        auto& visible=page.rows.back();auto cash=index.need_by_arrear.find(assessment->cash.id);if(cash!=index.need_by_arrear.end())visible.cash_need=cash->second;auto grain=index.need_by_arrear.find(assessment->grain.id);if(grain!=index.need_by_arrear.end())visible.grain_need=grain->second;
    }
    if(offset<static_cast<Integer>(sources->size()))page.next_cursor=LocalEconomyCursor{page.identity,query.observer_actor_id,query.place_id,query.authority,offset};return {true,std::move(page),{}};
}
// 结果只含原应付、实付、欠额和粮食来源；预计收入或实际钱包余额不在本页伪造。
BoundaryValue encode_fiscal_settlement_page(const FiscalSettlementPage& page){using V=BoundaryValue;V::Array rows;for(const auto& row:page.rows){StableId mode;switch(row.mode){case FiscalTaxMode::lenient:mode="lenient";break;case FiscalTaxMode::normal:mode="normal";break;case FiscalTaxMode::surcharge:mode="surcharge";break;}if(mode.empty())boundary::fail("InvalidFiscalTaxMode","/fiscal_settlement");rows.push_back(boundary::obj({{"kind",V{"tax_assessment"}},{"assessment_id",V{row.assessment_id}},{"period_id",V{row.period_id}},{"source_id",V{row.source_id}},{"site_id",V{row.site_id}},{"jurisdiction_id",V{row.jurisdiction_id}},{"organization_id",V{row.organization_id}},{"grain_item_id",V{row.grain_item_id}},{"policy_fact_id",V{row.policy_fact_id}},{"due_tick",V{row.due_tick}},{"mode",V{mode}},{"cash_due",V{row.cash_due}},{"cash_paid",V{row.cash_paid}},{"cash_outstanding",V{row.cash_outstanding}},{"grain_due",V{row.grain_due}},{"grain_paid",V{row.grain_paid}},{"grain_outstanding",V{row.grain_outstanding}},{"produced_grain",V{row.produced_grain}},{"civilian_grain_reserve",V{row.civilian_grain_reserve}}}));auto& encoded=rows.back();for(const auto& ref:std::vector<std::pair<StableId,std::optional<FiscalNeedReference>>>{{"cash_need",row.cash_need},{"grain_need",row.grain_need}})if(ref.second){const auto& need=*ref.second;if(need.status!="open"&&need.status!="partial"&&need.status!="fulfilled")boundary::fail("InvalidFiscalNeedReference","/fiscal_settlement");encoded.as<V::Dict>()->emplace_back(ref.first,boundary::obj({{"need_id",V{need.need_id}},{"source_fact_id",V{need.source_fact_id}},{"status",V{need.status}},{"revision",V{need.revision}}}));}}auto out=common_page_fields(page);out.find("rows")->data=std::move(rows);return out;}
}
